{
  "name": "Zahner设备搜索器",
  "name_en": "Zahner Device Searcher",
  "manufacturer": "Zahner",
  "description": "用于发现和选择Zahner仪器串口接口的软件组件（非物理设备）。它通过USB VID/PID与*IDN?查询识别已连接的Zahner设备，并返回命令口、数据口及相关串口信息，便于电化学仪器接入、通信配置和校准辅助。",
  "description_en": "A software component for discovering and selecting serial interfaces of Zahner instruments; it is not a physical device. It identifies connected Zahner devices using USB VID/PID information and *IDN? queries, then returns command, data, and related serial-port information to support instrument connection, communication setup, and calibration assistance.",
  "actions": [
    {
      "action_name": "auto-searchDevices",
      "description": "扫描计算机上的串口，并通过*IDN?命令搜索已连接设备。",
      "description_en": "Scan serial ports on the computer and search for connected devices using the *IDN? command."
    },
    {
      "action_name": "auto-searchZahnerDevices",
      "description": "结合Zahner的USB VID/PID和*IDN?查询搜索已连接的Zahner设备。",
      "description_en": "Search for connected Zahner devices using Zahner USB VID/PID information together with *IDN? queries."
    },
    {
      "action_name": "auto-searchSerialInterfacesWithZahnerVIDPID",
      "description": "按Zahner的USB VID/PID枚举并筛选对应的串口接口。",
      "description_en": "Enumerate and filter serial interfaces by Zahner USB VID/PID."
    },
    {
      "action_name": "auto-searchDevicesWithIDN",
      "description": "对指定或全部串口发送*IDN?，根据响应识别设备。",
      "description_en": "Send *IDN? to specified or all serial ports and identify devices from their responses."
    },
    {
      "action_name": "auto-selectDevice",
      "description": "从已发现设备中按序列号选择设备；未指定时选择第一个。",
      "description_en": "Select a discovered device by serial number; if none is given, select the first one."
    },
    {
      "action_name": "auto-getCommandInterface",
      "description": "获取所选设备的命令串口名称。",
      "description_en": "Get the command serial interface name of the selected device."
    },
    {
      "action_name": "auto-getDataInterface",
      "description": "获取所选设备的数据串口名称。",
      "description_en": "Get the data serial interface name of the selected device."
    },
    {
      "action_name": "auto-getMultimeterPort",
      "description": "获取连接校准用万用表的串口名称。",
      "description_en": "Get the serial port name connected to the calibration multimeter."
    }
  ],
  "tag_hints": [
    "SCPI device discovery",
    "serial port enumeration",
    "Zahner potentiostat",
    "USB VID PID matching",
    "*IDN? identification",
    "instrument connection setup",
    "calibration multimeter port lookup"
  ]
}

